unsafe extern "C" fn xmlFileOpenW(
    mut filename: *const c_char,
) -> *mut c_void {
    let mut path: *const c_char = ::core::ptr::null::<c_char>();
    let mut fd: *mut FILE = ::core::ptr::null_mut::<FILE>();
    if strcmp(filename, b"-\0" as *const u8 as *const c_char) == 0 {
        fd = stdout;
        return fd as *mut c_void;
    }
    if xmlStrncasecmp(
        filename as *mut xmlChar,
        b"file://localhost/\0" as *const u8 as *const c_char as *mut xmlChar,
        17 as c_int,
    ) == 0
    {
        path = filename.offset(16 as c_int as isize) as *const c_char;
    } else if xmlStrncasecmp(
        filename as *mut xmlChar,
        b"file:///\0" as *const u8 as *const c_char as *mut xmlChar,
        8 as c_int,
    ) == 0
    {
        path = filename.offset(7 as c_int as isize) as *const c_char;
    } else {
        path = filename;
    }
    if path.is_null() {
        return ::core::ptr::null_mut::<c_void>();
    }
    fd = fopen(path, b"wb\0" as *const u8 as *const c_char);
    if fd.is_null() {
        xmlIOErr(0 as c_int, path);
    }
    return fd as *mut c_void;
}

